def gen(rng):
    letters = 'abcdefghijklmnopqrstuvwxyz'
    def rs(n, a):
        return ''.join(rng.choice(letters[:a]) for _ in range(n))
    def fmt(s, k):
        return s + '\n' + str(k)
    tests = [fmt('a', 1), fmt('a', 5), fmt('ab', 1), fmt('aaaa', 3), fmt('abcabc', 1), fmt('xyzzyxxw', 2), fmt('abcdef', 6), fmt('abcdef', 100000), fmt('aabbcc', 2)]
    for _ in range(30):
        n = rng.randint(1, 14)
        a = rng.choice([2, 3, 4, 26])
        tests.append(fmt(rs(n, a), rng.randint(1, 6)))
    N = 200000
    tests.append(fmt(rs(N, 26), 5))
    tests.append(fmt('a' * N, 1))
    tests.append(fmt(rs(N, 2), 1))
    tests.append(fmt(rs(N, 26), 100000))
    tests.append(fmt(('abcdefghij' * (N // 10)), 10))
    tests.append(fmt(rs(N, 6), 3))
    return tests
